# ============================================================
# LS command
# ============================================================

def cmd_ls(args):
    """ls command - list directory sizes"""
    db_path = get_db_path(args)
    conn = open_db(db_path)

    use_bytes = getattr(args, 'bytes', False)
    use_apparent = getattr(args, 'apparent', False)
    use_color = getattr(args, 'color', False) and sys.stdout.isatty()
    use_classify = getattr(args, 'classify', False)
    use_graph = getattr(args, 'graph', False)
    use_recursive = getattr(args, 'recursive', False)
    use_name_sort = getattr(args, 'name_sort', False)
    use_count = getattr(args, 'count', False)
    dirs_only = getattr(args, 'dirs_only', False)
    full_path = getattr(args, 'full_path', False)
    max_levels = getattr(args, 'levels', 4) or 4
    use_ascii = getattr(args, 'ascii', False)
    directory_mode = getattr(args, 'directory', False)

    paths = getattr(args, 'paths', None) or ['.']

    for path in paths:
        path = os.path.abspath(path) if path != '.' else os.getcwd()
        path = path.rstrip('/')

        if directory_mode:
            # Show the directory itself
            root_data = db_get(conn, path)
            if root_data is None:
                # Try to find it as a subdirectory
                print(f'Path {path} not found in database', file=sys.stderr)
                print(f"The requested path '{path}' was not found in the database,", file=sys.stderr)
                print(f"Please run 'duc info' for a list of available directories.", file=sys.stderr)
                conn.close()
                sys.exit(1)
            info = parse_root_key(root_data)
            size = info['total_apparent'] if use_apparent else info['total_actual']
            if use_count:
                size = info['total_items']
            size_str = fmt_size(size, use_bytes)
            print(f'{size_str} {path}')
            continue

        if use_recursive:
            ls_recursive(conn, path, args, '', 0, max_levels, use_ascii)
        else:
            children = get_dir_contents_for_ls(conn, path)
            if children is None:
                print(f'Path {path} not found in database', file=sys.stderr)
                print(f"The requested path '{path}' was not found in the database,", file=sys.stderr)
                print(f"Please run 'duc info' for a list of available directories.", file=sys.stderr)
                conn.close()
                sys.exit(1)

            # Filter dirs only
            if dirs_only:
                children = [c for c in children if c['type'] == FILE_TYPE_DIR]

            # Sort
            if use_name_sort:
                children.sort(key=lambda x: x['name'])
            else:
                children.sort(key=lambda x: (x['apparent'] if use_apparent else x['actual']), reverse=True)

            # Find max for graph
            if use_graph and children:
                max_size = max(c['apparent'] if use_apparent else c['actual'] for c in children)
            else:
                max_size = 0

            for child in children:
                size = child['apparent'] if use_apparent else child['actual']
                if use_count:
                    size = child['count']

                size_str = fmt_size(size, use_bytes)

                name = child['name']
                if use_classify:
                    if child['type'] == FILE_TYPE_DIR:
                        name += '/'

                if use_graph and max_size > 0:
                    bar_len = 55
                    filled = int(size * bar_len / max_size)
                    bar = '+' * filled + ' ' * (bar_len - filled)
                    print(f'{size_str} {name:<20} [{bar}]')
                else:
                    print(f'{size_str} {name}')

    conn.close()

def get_dir_contents_for_ls(conn, path):
    """Get directory contents for ls command"""
    # Check if path is a direct root key
    root_data = db_get(conn, path)
    if root_data is not None:
        info = parse_root_key(root_data)
        child_key = info['child_key']
        dir_data = db_get(conn, child_key)
        if dir_data is not None:
            return parse_dir_entry_children(dir_data)

    # Try traversal from indexed roots
    reports = db_get(conn, 'duc_index_reports')
    if reports is None:
        return None

    for i in range(0, len(reports), REPORT_RECORD_SIZE):
        record = reports[i:i+REPORT_RECORD_SIZE]
        null_pos = record.find(b'\x00')
        if null_pos == 0:
            continue
        if null_pos == -1:
            root_path = record.decode('utf-8', errors='replace').rstrip('\x00')
        else:
            root_path = record[:null_pos].decode('utf-8', errors='replace')

        if not root_path:
            continue

        if path == root_path or path.startswith(root_path + '/'):
            result = traverse_path(conn, root_path, path)
            if result is not None:
                return result

    return None

# Tree drawing characters
TREE_CHARS = {
    'utf8': {
        'first': ' \u256f\u252c\u2500',  # ╯┬─ -> space + ╰ + ┬ + ─
        'middle': '  \u251c\u2500',       # space space ├ ─
        'last': '  \u2570\u2500',         # space space ╰ ─
        'cont_nolast': '  \u2502 ',       # space space │ space
        'cont_last': '    ',              # 4 spaces
    },
    'ascii': {
        'first': ' `+-',   # space backtick plus minus
        'middle': '  |-',  # space space pipe minus
        'last': '  `-',    # space space backtick minus
        'cont_nolast': '  | ',  # space space pipe space
        'cont_last': '    ',    # 4 spaces
    }
}

def ls_recursive(conn, path, args, prefix, depth, max_levels, use_ascii):
    """Recursively list directories"""
    use_apparent = getattr(args, 'apparent', False)
    use_bytes = getattr(args, 'bytes', False)
    use_name_sort = getattr(args, 'name_sort', False)
    use_count = getattr(args, 'count', False)
    use_classify = getattr(args, 'classify', False)
    full_path = getattr(args, 'full_path', False)
    dirs_only = getattr(args, 'dirs_only', False)
    max_ls_levels = getattr(args, 'levels', 4) or 4

    chars = TREE_CHARS['ascii'] if use_ascii else TREE_CHARS['utf8']

    children = get_dir_contents_for_ls(conn, path)
    if children is None:
        return

    if dirs_only:
        children = [c for c in children if c['type'] == FILE_TYPE_DIR]

    if use_name_sort:
        children.sort(key=lambda x: x['name'])
    else:
        children.sort(key=lambda x: x['apparent'] if use_apparent else x['actual'], reverse=True)

    n = len(children)
    for idx, child in enumerate(children):
        is_first = (idx == 0)
        is_last = (idx == n - 1)
        is_middle = not is_first and not is_last

        if is_first:
            tree = chars['first']
        elif is_last:
            tree = chars['last']
        else:
            tree = chars['middle']

        size = child['apparent'] if use_apparent else child['actual']
        if use_count:
            size = child['count']

        size_str = fmt_size(size, use_bytes)

        name = child['name']
        if use_classify:
            if child['type'] == FILE_TYPE_DIR:
                name += '/'

        if full_path:
            # Show full path without tree chars
            full_name = os.path.join(path, name.rstrip('/'))
            if child['type'] == FILE_TYPE_DIR:
                print(f'{size_str} {child["name"]}/')
            else:
                print(f'{size_str} {child["name"]}')
            if child['type'] == FILE_TYPE_DIR and child['child_key'] is not None:
                child_path = os.path.join(path, child['name'])
                ls_recursive_full_path(conn, child_path, args, depth+1, max_ls_levels)
        else:
            print(f'{size_str}{prefix}{tree} {name}')

            if child['type'] == FILE_TYPE_DIR and child['child_key'] is not None:
                if depth + 1 < max_ls_levels:
                    # Determine next level's prefix continuation
                    if is_last:
                        next_cont = chars['cont_last']
                    else:
                        next_cont = chars['cont_nolast']

                    child_path = os.path.join(path, child['name'])
                    ls_recursive(conn, child_path, args, prefix + next_cont, depth+1, max_ls_levels, use_ascii)

def ls_recursive_full_path(conn, path, args, depth, max_levels):
    """Recursive listing with full paths"""
    if depth >= max_levels:
        return

    use_apparent = getattr(args, 'apparent', False)
    use_bytes = getattr(args, 'bytes', False)
    use_name_sort = getattr(args, 'name_sort', False)
    use_count = getattr(args, 'count', False)
    use_classify = getattr(args, 'classify', False)
    dirs_only = getattr(args, 'dirs_only', False)

    children = get_dir_contents_for_ls(conn, path)
    if children is None:
        return

    if dirs_only:
        children = [c for c in children if c['type'] == FILE_TYPE_DIR]

    if use_name_sort:
        children.sort(key=lambda x: x['name'])
    else:
        children.sort(key=lambda x: x['apparent'] if use_apparent else x['actual'], reverse=True)

    for child in children:
        size = child['apparent'] if use_apparent else child['actual']
        if use_count:
            size = child['count']

        size_str = fmt_size(size, use_bytes)

        rel_path = os.path.join(path, child['name'])
        # Make it relative to the query path
        # (We need the base path from the original ls call)
        name = rel_path

        if use_classify and child['type'] == FILE_TYPE_DIR:
            name += '/'

        print(f'{size_str} {child["name"]}{"/" if child["type"]==FILE_TYPE_DIR and use_classify else ""}')

        if child['type'] == FILE_TYPE_DIR and child['child_key'] is not None:
            ls_recursive_full_path(conn, rel_path, args, depth+1, max_levels)

