def dir_to_json(conn, path, depth=0, apparent=False, exclude_files=False, min_size=0):
    """Convert directory to JSON structure"""
    root_data = db_get(conn, path)
    if root_data is not None:
        info = parse_root_key(root_data)
        child_key = info['child_key']
        size_apparent = info['total_apparent']
        size_actual = info['total_actual']
        count = info['total_items']

        children = []
        dir_data = db_get(conn, child_key)
        if dir_data:
            raw_children = parse_dir_entry_children(dir_data)
            for child in sorted(raw_children, key=lambda x: x['apparent'], reverse=True):
                if min_size > 0:
