def read_config():
    """Read duc configuration files"""
    config = {}

    config_paths = [
        '/etc/ducrc',
        os.path.expanduser('~/.config/duc/ducrc'),
        os.path.expanduser('~/.ducrc'),
        './.ducrc',
    ]

    current_section = 'global'

    for config_path in config_paths:
        if not os.path.exists(config_path):
            continue
        try:
            with open(config_path, 'r') as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith('#'):
                        continue
                    if line.startswith('[') and line.endswith(']'):
                        current_section = line[1:-1]
                        if current_section not in config:
                            config[current_section] = {}
                    else:
                        parts = line.split(None, 1)
                        key = parts[0]
                        val = parts[1] if len(parts) > 1 else True
                        if current_section not in config:
                            config[current_section] = {}
                        config[current_section][key] = val
        except Exception:
            pass

    return config

def apply_config(config, section, args):
    """Apply configuration to args"""
    # Apply global config
    for key, val in config.get('global', {}).items():
        if key == 'database' and not getattr(args, 'database', None):
            args.database = val

    # Apply section-specific config
    for key, val in config.get(section, {}).items():
        attr = key.replace('-', '_')
        if not getattr(args, attr, None):
            if val is True:
                setattr(args, attr, True)
            else:
                setattr(args, attr, val)

